import { unstable_after } from 'next/server';
import { cookies } from 'next/headers';

async function logToAnalytics(page: string) {
  const cookieStore = await cookies();
  const sessionId = cookieStore.get('session-id')?.value || 'anonymous';

  console.log(`[Analytics] Page view: ${page}, Session: ${sessionId}, Timestamp: ${new Date().toISOString()}`);
}

export default function Home() {
  unstable_after(() => {
    logToAnalytics('/');
  });

  return (
    <main>
      <h1>Welcome</h1>
      <p>Please implement page view logging that doesn't block the response.</p>
    </main>
  );
}
